/**
 * Scratch probe (not part of the repo): reproduce the blank map that
 * 04-zeitreise.png showed in the 151/151 run and report the layer state.
 *
 *   node /tmp/probe-overlay.mjs http://127.0.0.1:8787 /tmp/look
 */
import { spawn } from 'node:child_process';
import { writeFile, mkdir } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

const BASE_URL = process.argv[2] ?? 'http://127.0.0.1:8787';
const OUT = process.argv[3] ?? '/tmp/look';
const DEBUG_PORT = 9333;
const CHROME = process.env.CHROME_PATH || '/usr/bin/google-chrome';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

await mkdir(OUT, { recursive: true });
const userDataDir = path.join(os.tmpdir(), `probe-chrome-${process.pid}`);
const chrome = spawn(
  CHROME,
  [
    '--headless=new',
    '--no-sandbox',
    '--disable-gpu',
    '--disable-dev-shm-usage',
    '--hide-scrollbars',
    '--window-size=1440,960',
    `--remote-debugging-port=${DEBUG_PORT}`,
    `--user-data-dir=${userDataDir}`,
    'about:blank',
  ],
  { stdio: ['ignore', 'pipe', 'pipe'] },
);

const deadline = Date.now() + 30_000;
let target = null;
while (Date.now() < deadline) {
  try {
    const res = await fetch(`http://127.0.0.1:${DEBUG_PORT}/json/version`);
    if (res.ok) {
      for (const method of ['PUT', 'GET']) {
        const t = await fetch(`http://127.0.0.1:${DEBUG_PORT}/json/new?about:blank`, { method });
        if (t.ok) {
          target = (await t.json()).webSocketDebuggerUrl;
          break;
        }
      }
      if (target) break;
    }
  } catch {}
  await sleep(300);
}
if (!target) {
  console.error('no devtools target');
  process.exit(2);
}

const ws = new WebSocket(target);
await new Promise((res, rej) => {
  ws.addEventListener('open', res, { once: true });
  ws.addEventListener('error', rej, { once: true });
});
let id = 0;
const pending = new Map();
ws.addEventListener('message', (event) => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const mid = ++id;
    pending.set(mid, { resolve, reject });
    ws.send(JSON.stringify({ id: mid, method, params }));
  });

await send('Page.enable');
await send('Runtime.enable');

async function evaluate(expression) {
  const res = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  if (res.exceptionDetails) throw new Error(res.exceptionDetails.exception?.description ?? 'eval failed');
  return res.result.value;
}

async function shot(name) {
  const res = await send('Page.captureScreenshot', { format: 'png' });
  await writeFile(path.join(OUT, name), Buffer.from(res.data, 'base64'));
}

const LAYERS = `(() => {
  const map = document.querySelector('#map');
  const layers = [...document.querySelectorAll('#map .map-layer')].map((layer) => ({
    cls: layer.className,
    z: getComputedStyle(layer).zIndex,
    opacity: getComputedStyle(layer).opacity,
    display: getComputedStyle(layer).display,
    tiles: layer.querySelectorAll('img').length,
    broken: [...layer.querySelectorAll('img')].filter((img) => img.complete && img.naturalWidth === 0).length,
    first: layer.querySelector('img')?.src?.slice(-46) ?? '',
  }));
  return {
    layers,
    markers: document.querySelectorAll('#map .map-marker').length,
    clusters: document.querySelectorAll('#map .map-cluster').length,
    mapRect: map ? { w: Math.round(map.getBoundingClientRect().width), h: Math.round(map.getBoundingClientRect().height) } : null,
    rows: document.querySelectorAll('#result-list > *').length,
    search: location.search,
  };
})()`;

await send('Page.navigate', { url: `${BASE_URL}/?from=1546&to=1850` });
for (let i = 0; i < 40; i += 1) {
  if ((await evaluate(`document.querySelectorAll('#result-list > *').length`)) > 0) break;
  await sleep(250);
}
await sleep(2500);
console.log('BEFORE overlay:', JSON.stringify(await evaluate(LAYERS)));
await shot('probe-before-overlay.png');

const applied = await evaluate(`(() => {
  const select = document.querySelector('#overlay-select');
  if (!select) return 'no select';
  const option = [...select.options].filter((o) => o.value).find((o) => o.value === 'ch.swisstopo.zeitreihen') ?? [...select.options].find((o) => /hiks|zeitreihen/.test(o.value));
  if (!option) return 'no option';
  select.value = option.value;
  select.dispatchEvent(new Event('change', { bubbles: true }));
  return option.value;
})()`);
console.log('applied overlay:', applied);
await sleep(4000);
console.log('AFTER overlay:', JSON.stringify(await evaluate(LAYERS)));
await shot('probe-after-overlay.png');

// The harness takes 04-zeitreise.png right after a WCAG contrast sweep over the
// whole page; run that too and look again, in case the sweep is what blanked it.
await evaluate(`(() => { window.scrollTo(0, 0); return true; })()`);
await sleep(1200);
console.log('AFTER scroll-top:', JSON.stringify(await evaluate(LAYERS)));
await shot('probe-after-scroll.png');

ws.close();
chrome.kill('SIGTERM');

