/* ---- Result density: rows or the card gallery (maps-2) ----
   `#result-list[data-density='cards']` draws the *same* rows as image cards: the
   thumbnail becomes the card's face, the text sits underneath, and the list
   flows into as many columns as the column has room for. Nothing about the DOM,
   the focus order or the live region changes — browsing maps is a visual task,
   so this is a drawing of the same result (URL key `dn=cards`). */
.app-results__head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--zh-size-tiny) var(--zh-size-small-regular);
  margin-bottom: var(--zh-size-small-regular);
}

.app-results__head .zh-heading--4 {
  margin: 0;
  flex: 1 1 auto;
}

.app-density {
  flex: 0 0 auto;
}

.app-result-list[data-density='cards'] {
  grid-template-columns: repeat(auto-fill, minmax(min(220px, 100%), 1fr));
  align-items: stretch;
}

.app-result-list[data-density='cards'] > li {
  display: flex;
}

/* One column per card, so the picture is the face of the card and the text is
   readable underneath instead of squeezed next to a 64 px thumbnail. */
.app-result-list[data-density='cards'] .zh-result {
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto 1fr;
  gap: var(--zh-size-small-regular);
  width: 100%;
}

.app-result-list[data-density='cards'] .zh-result__thumb {
  width: 100%;
  height: 132px;
}

/* A card has room for the whole title; `-webkit-line-clamp` still guards a
   runaway one. */
.app-result-list[data-density='cards'] .zh-result__title {
  -webkit-line-clamp: 5;
}

/* The card mode is a display choice, so it must be honest in the list-only view
   (which is wider) and on a phone (one column, no horizontal overflow). */
.app-view--list .app-result-list[data-density='cards'] {
  grid-template-columns: repeat(auto-fill, minmax(min(240px, 100%), 1fr));
}

