arguments.content:
/**
 * Result density: the list as rows or as the card gallery (maps-2).
 *
 * Browsing historical maps is visual, so the result list can be drawn as a
 * thumbnail gallery (`?dn=cards`). The choice is a *display* choice like the
 * view switch (`?view=`), which is what these tests pin down: it round-trips
 * through the URL, a hand-written value falls back to rows, and it is not a
 * browser-history step — one “back” must still undo the search, not the layout.
 */
import test from 'node:test';
import assert from 'node:assert/strict';

import { HISTORY_PUSH_KEYS, STATE_DEFAULTS, readStateFromUrl, sanitise, stateToQuery } from '../public/app/store.js';

test('the result list defaults to rows and the default stays out of the URL', () => {
  assert.equal(STATE_DEFAULTS.density, 'rows');
  assert.equal(stateToQuery({ ...STATE_DEFAULTS }), '');
});

test('the card gallery round-trips through the short URL key "dn"', () => {
  const query = stateToQuery({ ...STATE_DEFAULTS, density: 'cards', q: 'Zürich' });
  assert.equal(new URLSearchParams(query).get('dn'), 'cards');
  assert.equal(readStateFromUrl(`?${query}`).density, 'cards');
  // …and the default is not written back when it is chosen again.
  assert.equal(stateToQuery({ ...STATE_DEFAULTS, density: 'rows', q: 'Zürich' }).includes('dn='), false);
});

test('a hand-written density falls back to rows instead of breaking the list', () => {
  assert.equal(sanitise({ ...STATE_DEFAULTS, density: 'galerie' }).density, 'rows');
  assert.equal(sanitise({ ...STATE_DEFAULTS, density: undefined }).density, 'rows');
  assert.equal(sanitise({ ...STATE_DEFAULTS, density: 'CARDS' }).density, 'rows');
  assert.equal(sanitise({ ...STATE_DEFAULTS, density: 'cards' }).density, 'cards');
  assert.equal(readStateFromUrl('?dn=').density, 'rows');
});

test('the density is a display choice, not a history step (D6)', () => {
  assert.equal(HISTORY_PUSH_KEYS.includes('density'), false);
});
